definition.script:
import groovy.json.JsonSlurper

def build_hashes = [:]
def retrieveBuildSpecId
def pipelineBuildId
def hasOverrideUI
def targetStack

@NonCPS
def parseBuildHashes(String text) {
    def spec = new JsonSlurper().parseText(text)
    def result = [:]
    for (build in spec.application) {
        result[build.project_job_git_key.toString()] = build.git_hash?.toString()
    }
    return result
}

pipeline {
    agent any

    environment {
        SOURCE_SCRIPTS_FOLDER = "${JENKINS_HOME}/workspace/Bash_Functions/"
    }

    stages {
        stage('Retrieve Build Spec') {
            steps {
                script {
                    def result = build job: 'Retrieve Build Spec'
                    retrieveBuildSpecId = result.number
                }
                script {
                    copyArtifacts filter: '*', projectName: 'Retrieve Build Spec', selector: specific(""+retrieveBuildSpecId)
                    // parseBuildHashes returns a plain (serializable) LinkedHashMap.
                    // The lazy JSON structures never leave the @NonCPS method.
                    build_hashes.putAll(parseBuildHashes(readFile('build-spec.json')))
                    pipelineBuildId = readFile('pipeline_git_commit.txt').trim()
                    if (build_hashes['OVERRIDE_UI']) {
                        hasOverrideUI = true;
                        echo "Hex Code: OVERRIDE_UI = Color Name: ${build_hashes['OVERRIDE_UI']}"
                    }
                }
            }
        }
        stage('Retrieve Stack') {
            steps {
                script {
                    targetStack = sh(script: """
                    bash -c '
                    set +x
                    for script_file in "$SOURCE_SCRIPTS_FOLDER"*.sh; do
                        chmod +x "\$script_file"
                        if [ -f "\$script_file" ] && [ -x "\$script_file" ]; then
                            . "\$script_file"
                        fi
                    done
                    # The PIC-SURE Pipeline is always used to build for staging.
                    get_stack \"staging\"
                    '
                    """, returnStdout: true).trim()
                    println "TARGET_STACK: $targetStack"
                }
            }
        }
        stage('Build') {
            steps {
                script {
                    // One lock per RESOLVED physical stack: same-stack runs queue,
                    // the other stack proceeds. Covers reactor + image wave so no
                    // second run can rebuild this lane mid-packaging.
                    lock("stack-${targetStack}") {
                        if (build_hashes['PSA']) {
                            build job: 'PIC-SURE Maven Build', parameters: [
                                [$class: 'StringParameterValue', name: 'git_hash', value: build_hashes['PSA']],
                                [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                                [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]
                            ]
                        } else {
                            echo 'No PSA hash in the build spec. Skipping monorepo build.'
                        }

                        def imageParams = [
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                            [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]
                        ]
                        def branches = [:]
                        if (build_hashes['PSA']) {
                            branches['gateway']       = { build job: 'PIC-SURE Gateway Image', parameters: imageParams }
                            branches['operations']    = { build job: 'PIC-SURE Operations Service Image', parameters: imageParams }
                            branches['query']         = { build job: 'PIC-SURE HPDS Query Service Image', parameters: imageParams }
                            branches['hpds']          = { build job: 'PIC-SURE HPDS Image', parameters: imageParams }
                            branches['psama']         = { build job: 'PIC-SURE Auth Micro App Image', parameters: imageParams }
                            branches['logging']       = { build job: 'PIC-SURE Logging Image', parameters: imageParams }
                            branches['visualization'] = { build job: 'PIC-SURE Visualization Image', parameters: imageParams }
                            branches['dictionary']    = { build job: 'PIC-SURE Dictionary Image', parameters: imageParams }
                        }
                        branches['frontend'] = {
                            build job: 'PIC-SURE Frontend Build', parameters: [
                                [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                                [$class: 'StringParameterValue', name: 'git_hash', value: build_hashes['PSF']]
                            ]
                        }
                        parallel branches
                    }
                }
            }
        }
    }
}
